/*! coi-serviceworker v0.1.7 - Guido Zuidhof and contributors, licensed under MIT; MasteryCoach patched navigation fallback */
let coepCredentialless = false;

if (typeof window === "undefined") {
    self.addEventListener("install", () => self.skipWaiting());
    self.addEventListener("activate", event => event.waitUntil(self.clients.claim()));
    self.addEventListener("message", event => {
        if (!event.data) {
            return;
        }

        if (event.data.type === "deregister") {
            self.registration.unregister()
                .then(() => self.clients.matchAll())
                .then(clients => {
                    clients.forEach(client => client.navigate(client.url));
                });
            return;
        }

        if (event.data.type === "coepCredentialless") {
            coepCredentialless = event.data.value;
        }
    });

    function withIsolationHeaders(response) {
        if (response.status === 0) {
            return response;
        }

        const headers = new Headers(response.headers);
        headers.set("Cross-Origin-Embedder-Policy", coepCredentialless ? "credentialless" : "require-corp");
        if (!coepCredentialless) {
            headers.set("Cross-Origin-Resource-Policy", "cross-origin");
        }
        headers.set("Cross-Origin-Opener-Policy", "same-origin");
        return new Response(response.body, {
            status: response.status,
            statusText: response.statusText,
            headers
        });
    }

    function fetchWithIsolation(request) {
        const isolatedRequest = coepCredentialless && request.mode === "no-cors"
            ? new Request(request, { credentials: "omit" })
            : request;
        return fetch(isolatedRequest).then(withIsolationHeaders);
    }

    function reportFetchFailure(request, error) {
        const message = error?.message || String(error);
        return self.clients.matchAll({ type: "window", includeUncontrolled: true })
            .then(clients => {
                for (const client of clients) {
                    client.postMessage({
                        type: "mc-service-worker-fetch-failed",
                        url: request.url,
                        message
                    });
                }
            })
            .catch(reportFailure => console.error(
                "Unable to report a COI service-worker fetch failure:", reportFailure));
    }

    self.addEventListener("fetch", event => {
        const request = event.request;
        if (request.cache === "only-if-cached" && request.mode !== "same-origin") {
            return;
        }

        event.respondWith(
            fetchWithIsolation(request).catch(error => {
                console.error(error);
                event.waitUntil(reportFetchFailure(request, error));

                if (request.mode === "navigate") {
                    return fetchWithIsolation(new Request(self.registration.scope, {
                        headers: request.headers,
                        credentials: "same-origin"
                    }));
                }

                // A synthetic success (or 502 body) turns a failed module fetch into an opaque
                // import error. Preserve the network failure so the caller can diagnose it.
                return Response.error();
            })
        );
    });
} else {
    (() => {
        const options = {
            shouldRegister: () => true,
            shouldDeregister: () => false,
            coepCredentialless: () => !(window.chrome || window.netscape),
            doReload: () => window.location.reload(),
            quiet: false,
            ...window.coi
        };
        const nav = navigator;

        if (nav.serviceWorker && nav.serviceWorker.controller) {
            nav.serviceWorker.controller.postMessage({
                type: "coepCredentialless",
                value: options.coepCredentialless()
            });
            if (options.shouldDeregister()) {
                nav.serviceWorker.controller.postMessage({ type: "deregister" });
            }
        }

        if (window.crossOriginIsolated === false && options.shouldRegister()) {
            if (window.isSecureContext) {
                nav.serviceWorker && nav.serviceWorker.register(window.document.currentScript.src).then(
                    registration => {
                        if (!options.quiet) {
                            console.log("COOP/COEP Service Worker registered", registration.scope);
                        }
                        registration.addEventListener("updatefound", () => {
                            if (!options.quiet) {
                                console.log("Reloading page to make use of updated COOP/COEP Service Worker.");
                            }
                            options.doReload();
                        });
                        if (registration.active && !nav.serviceWorker.controller) {
                            if (!options.quiet) {
                                console.log("Reloading page to make use of COOP/COEP Service Worker.");
                            }
                            options.doReload();
                        }
                    },
                    error => {
                        if (!options.quiet) {
                            console.error("COOP/COEP Service Worker failed to register:", error);
                        }
                    });
            } else if (!options.quiet) {
                console.log("COOP/COEP Service Worker not registered, a secure context is required.");
            }
        }
    })();
}
